<script setup lang="ts">
import {computed,ref} from 'vue';
import type {Point,Study} from './model.ts';
const props=defineProps<{study:Study;position?:Point}>();defineEmits<{close:[]}>();
const span=ref(160),shift=ref({x:0,z:0}),selection=ref('Select a building or centerline for its original OSM ID.');
const center=computed(()=>({x:(props.position?.x??0)+shift.value.x,z:(props.position?.z??0)+shift.value.z}));
const box=computed(()=>`${center.value.x-span.value/2} ${center.value.z-span.value/2} ${span.value} ${span.value}`);
const near=(points:Point[])=>points.some(p=>Math.abs(p.x-center.value.x)<span.value*.7&&Math.abs(p.z-center.value.z)<span.value*.7);
const buildings=computed(()=>props.study.buildings.filter(b=>near(b.points))),roads=computed(()=>props.study.roads.filter(r=>near(r.points)));
const surfaces=computed(()=>props.study.roadSurface?.filter(s=>near([s.a,s.b]))??[]),walk=computed(()=>props.study.pedestrians?.pieces.filter(s=>near([s.a,s.b]))??[]);
const points=(p:Point[])=>p.map(v=>`${v.x},${v.z}`).join(' ');
const conflicts=computed(()=>props.study.roadConflicts?.filter(c=>buildings.value.some(b=>b.id===c.buildingId))??[]);
</script>
<template><section class="geometry-review" aria-label="World geometry overlay"><header><div><h2>World geometry review</h2><p>Orange: original centerline · slate: rendered road edges · copper: original buildings · green: pedestrian corridors · gold: crossings · red: conflict footprints.</p></div><button @click="$emit('close')">Close geometry overlay</button></header><div class="geometry-controls"><label>View width {{span}}m <input aria-label="Geometry view width" type="range" min="60" max="1700" step="10" v-model.number="span"></label><button v-for="[label,x,z] in [['North',0,-1],['West',-1,0],['East',1,0],['South',0,1]]" :key="label" @click="shift={x:shift.x+Number(x)*span/3,z:shift.z+Number(z)*span/3}">{{label}}</button><button @click="shift={x:0,z:0}">Player</button></div><svg :viewBox="box" aria-label="Road edges, source footprints, centerlines and pedestrian connections"><rect :x="center.x-span/2" :y="center.z-span/2" :width="span" :height="span" fill="#e4e8d5"/><line v-for="(s,i) in surfaces" :key="'s'+i" :x1="s.a.x" :y1="s.a.z" :x2="s.b.x" :y2="s.b.z" stroke="#435c64" :stroke-width="s.halfWidth*2" stroke-linecap="round"/><line v-for="(s,i) in walk" :key="'w'+i" :x1="s.a.x" :y1="s.a.z" :x2="s.b.x" :y2="s.b.z" :stroke="s.kind==='crossing'?'#deb53a':'#389866'" :opacity="s.component===study.pedestrians?.component?1:.3" :stroke-width="s.halfWidth*2" stroke-linecap="round"/><polygon v-for="b in buildings" :key="b.id" :points="points(b.points)" fill="#b58c67" :stroke="conflicts.some(c=>c.buildingId===b.id)?'#e42c33':'#5c493c'" stroke-width=".22" @click="selection='OSM building way/'+b.id+' '+JSON.stringify(b.tags)"><title>Building way/{{b.id}}</title></polygon><polyline v-for="r in roads" :key="r.id" :points="points(r.points)" fill="none" stroke="#e97525" stroke-width=".25" @click="selection='OSM road way/'+r.id+' '+JSON.stringify(r.tags)"><title>Road way/{{r.id}}</title></polyline><g v-if="span<=230"><text v-for="r in roads" :key="'t'+r.id" :x="r.points.find(p=>near([p]))?.x" :y="r.points.find(p=>near([p]))?.z" font-size="1.6" fill="#182f2a">way/{{r.id}}</text></g><circle :cx="position?.x??0" :cy="position?.z??0" r="1" fill="#095bac"/></svg><p class="selection">{{selection}}</p><details><summary>Nearby conflicts ({{conflicts.length}})</summary><p v-for="c in conflicts" :key="c.roadId+':'+c.buildingId+':'+c.segment">Road way/{{c.roadId}} · building way/{{c.buildingId}} · {{c.kind}} · {{c.clearanceM.toFixed(2)}}m · {{c.decision}}</p></details><p>Pedestrian offsets, crossings, widths and terrain are virtual styling. Faded green components are disconnected and not playable from this spawn. Original coordinates remain unchanged.</p></section></template>
<style scoped>.geometry-review{position:absolute;inset:12px;z-index:12;background:#fbfbf1;border-radius:12px;padding:16px;overflow:auto;font-size:12px}.geometry-review header{display:flex;justify-content:space-between;gap:20px}.geometry-review h2{margin:0}.geometry-review p{line-height:1.5}.geometry-review button{min-height:42px;padding:8px;border:1px solid #9eaf99;border-radius:6px;background:#e7eddd;color:#244b3c}.geometry-controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.geometry-review svg{width:100%;height:62vh;margin-top:12px}.selection{overflow-wrap:anywhere;font-family:monospace}@media(max-width:700px){.geometry-review header{display:block}.geometry-review svg{height:45vh}}</style>
